import{u as t}from"./chunks/useReporter.D4n0v9NN.js";import{E as i,c as s,o as l,j as a,I as r,b2 as o}from"./chunks/framework.BRCYMVIo.js";const n=a("div",{class:"tip custom-block"},[a("p",{class:"custom-block-title"},"TIP"),a("p",null,"V2Ray / Xray 是常见的代理网络内核，x-ui 是一个基于 Xray Core 的 Web 管理面板，可以用图形界面创建节点、管理用户、设置流量和过期时间。本文面向新手，目标是搭建一个个人学习和合法访问用途的自建节点。"),a("p",null,"请根据所在地法律法规合规使用相关技术，不要用于违法用途，也不要把面板账号、节点链接或订阅链接公开分享。")],-1),d=o(`<p>搭建完成后，你会得到一个 x-ui 管理面板，并可以在里面创建 VLESS、VMess、Trojan、Shadowsocks 等不同类型的入站配置。新手建议先用面板默认支持的稳定方案，跑通之后再调整更复杂的传输和 TLS 设置。</p><blockquote><p>Disclaimer: This project is only for personal learning and communication, please do not use it for illegal purposes, please do not use it in a production environment</p></blockquote><h2 id="前提条件" tabindex="-1">前提条件 <a class="header-anchor" href="#前提条件" aria-label="Permalink to &quot;前提条件&quot;">​</a></h2><ul><li>一台可通过 SSH 登录的海外 VPS 服务器；</li><li>一个域名，可选。如果你只是先测试，可以暂时使用服务器 IP；</li><li>一台用于连接的客户端设备，比如 Windows、macOS、Android 或 iPhone；</li><li>能复制并执行简单 Linux 命令。</li></ul><h2 id="购买国外的服务器" tabindex="-1">购买国外的服务器 <a class="header-anchor" href="#购买国外的服务器" aria-label="Permalink to &quot;购买国外的服务器&quot;">​</a></h2><p>自建节点的前提是先有一台可以访问海外网络的 VPS。常见选择有 <a href="https://www.vultr.com/?ref=7436511" target="_blank">Vultr</a>、<a href="https://nube.sh/invite/011895803HMMBY" target="_blank">Nube VPS</a> 等。</p><p>没有服务器的朋友可以先注册账号并购买最低配置的虚拟主机。个人学习用途通常 1CPU、512MB 内存就可以起步，后续如果连接人数或流量增加，再升级配置。</p><p>详细的注册和部署实例教程可以参考另一篇文章 <a href="./vultr.html" target="_blank">《优质的 VPS 搭建代理推荐》</a>。等你可以使用 SSH 远程登录到服务器，就可以继续往下操作。</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>系统建议选择 Debian 12 或 Ubuntu LTS。服务器刚开通后，先确认能用 <code>ssh root@服务器IP</code> 登录。</p></div><h2 id="安装-x-ui-面板" tabindex="-1">安装 x-ui 面板 <a class="header-anchor" href="#安装-x-ui-面板" aria-label="Permalink to &quot;安装 x-ui 面板&quot;">​</a></h2><p>登录到你的服务器，执行:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Ls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://x-ui.alireza0.dev/install.sh)</span></span></code></pre></div><p>这个脚本会安装 x-ui 面板和 Xray Core，并启动一个 Web 服务。安装完成后，终端通常会输出面板访问地址、端口、用户名和密码，请把这些信息保存好。</p><p>如果脚本询问是否继续安装、是否设置端口、是否配置用户名密码，新手可以先按提示操作。遇到不确定的选项，优先使用脚本推荐值，安装完成后再进入面板修改。</p><p>安装后也可以在服务器执行下面的命令查看菜单：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">x-ui</span></span></code></pre></div><p>常用操作包括查看面板信息、重启面板、更新 x-ui、修改面板端口和重置账号密码。</p><h2 id="首次登录后的安全设置" tabindex="-1">首次登录后的安全设置 <a class="header-anchor" href="#首次登录后的安全设置" aria-label="Permalink to &quot;首次登录后的安全设置&quot;">​</a></h2><p>浏览器打开脚本输出的面板地址，例如：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://服务器IP:面板端口/</span></span></code></pre></div><p>第一次登录后建议立刻完成这些设置：</p><ul><li>修改默认用户名和密码；</li><li>修改默认面板端口，避免继续使用容易被扫描的端口；</li><li>如果服务器提供商有防火墙规则，只开放 SSH 端口、面板端口和节点端口；</li><li>节点链接、二维码、订阅链接只给自己使用，不要发到公开页面；</li><li>后续定期执行 <code>x-ui</code> 菜单里的更新操作。</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>如果浏览器打不开面板，先检查 VPS 控制台的防火墙、安全组是否放行了面板端口，再检查服务器系统防火墙是否允许该端口访问。</p></div><h2 id="创建一个节点" tabindex="-1">创建一个节点 <a class="header-anchor" href="#创建一个节点" aria-label="Permalink to &quot;创建一个节点&quot;">​</a></h2><p>进入 x-ui 面板后，通常按下面的顺序操作：</p><ol><li>打开「入站列表」或「Inbounds」；</li><li>点击「添加入站」；</li><li>协议选择 <code>VLESS</code> 或 <code>VMess</code>，新手优先选择面板里默认提示最完整的方案；</li><li>端口填写一个没有被占用的端口，例如 <code>443</code>、<code>8443</code> 或其他自定义端口；</li><li>添加一个客户端，设置好备注、过期时间和流量限制；</li><li>保存配置，然后确认入站状态是启用。</li></ol><p>如果你有自己的域名，可以把域名解析到 VPS IP，再在面板里配置 TLS、证书或 Reality 等高级选项。没有域名时，先用 IP 跑通基本连接也可以。</p><h2 id="导出客户端配置" tabindex="-1">导出客户端配置 <a class="header-anchor" href="#导出客户端配置" aria-label="Permalink to &quot;导出客户端配置&quot;">​</a></h2><p>节点创建完成后，在入站列表里找到对应的客户端，复制分享链接、订阅链接，或者打开二维码。常见格式大概是：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vless://...</span></span>
<span class="line"><span>vmess://...</span></span>
<span class="line"><span>trojan://...</span></span></code></pre></div><p>客户端导入时不要手动改动这些链接，先直接导入并测试连接。确认能正常访问后，再回来优化协议、端口、流量和过期时间。</p><h2 id="客户端下载" tabindex="-1">客户端下载 <a class="header-anchor" href="#客户端下载" aria-label="Permalink to &quot;客户端下载&quot;">​</a></h2><p>不同系统使用的客户端不一样：</p><table tabindex="0"><thead><tr><th>系统</th><th>常见选择</th><th>配置方式</th></tr></thead><tbody><tr><td>Windows</td><td>v2rayN</td><td>导入分享链接或订阅链接</td></tr><tr><td>Android</td><td>v2rayNG</td><td>扫描二维码或导入链接</td></tr><tr><td>macOS</td><td>V2RayU、NekoRay、Clash Verge 等</td><td>导入链接或订阅</td></tr><tr><td>iPhone / iPad</td><td>Shadowrocket、Stash 等</td><td>扫描二维码或导入订阅</td></tr></tbody></table><p>新手不要直接下载 <code>v2ray-core</code> 或 <code>Xray-core</code> 当客户端使用。它们更偏向核心程序，图形客户端会帮你处理配置文件、订阅更新和连接切换。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="面板打不开" tabindex="-1">面板打不开 <a class="header-anchor" href="#面板打不开" aria-label="Permalink to &quot;面板打不开&quot;">​</a></h3><p>优先检查三件事：</p><ul><li>面板端口是否写对；</li><li>VPS 后台安全组是否放行面板端口；</li><li>服务器防火墙是否拦截了端口。</li></ul><h3 id="客户端导入后连不上" tabindex="-1">客户端导入后连不上 <a class="header-anchor" href="#客户端导入后连不上" aria-label="Permalink to &quot;客户端导入后连不上&quot;">​</a></h3><p>先确认节点端口已经放行，然后检查客户端里的地址、端口、协议、UUID、传输方式是否和 x-ui 面板一致。只要有一个字段不一致，就可能连接失败。</p><h3 id="能连上但速度慢" tabindex="-1">能连上但速度慢 <a class="header-anchor" href="#能连上但速度慢" aria-label="Permalink to &quot;能连上但速度慢&quot;">​</a></h3><p>自建节点速度主要受 VPS 线路、服务器地区、本地网络和晚高峰拥堵影响。可以优先换服务器地区，其次再考虑升级配置或更换服务商。</p><h3 id="要不要开多人共用" tabindex="-1">要不要开多人共用 <a class="header-anchor" href="#要不要开多人共用" aria-label="Permalink to &quot;要不要开多人共用&quot;">​</a></h3><p>不建议新手把自建节点当成多人服务。多人共用会带来流量、账号管理、安全和合规风险。个人学习用途，给每台设备单独建客户端会更清晰。</p><h2 id="参考链接" tabindex="-1">参考链接 <a class="header-anchor" href="#参考链接" aria-label="Permalink to &quot;参考链接&quot;">​</a></h2><ul><li><a href="https://github.com/alireza0/x-ui" target="_blank" rel="noreferrer">x-ui 官方仓库</a></li><li><a href="https://github.com/XTLS/Xray-core/releases" target="_blank" rel="noreferrer">Xray-core Releases</a></li><li><a href="https://github.com/v2fly/v2ray-core/releases" target="_blank" rel="noreferrer">V2Ray-core Releases</a></li><li><a href="https://github.com/2dust/v2rayN/releases" target="_blank" rel="noreferrer">v2rayN Releases</a></li></ul>`,47),m=JSON.parse('{"title":"小白自建 V2Ray/Xray 节点教程","description":"使用海外 VPS 和 x-ui 面板自建 V2Ray/Xray 节点，包含服务器准备、脚本安装、面板安全设置、节点创建和客户端导入流程。","frontmatter":{"title":"小白自建 V2Ray/Xray 节点教程","head":[["meta",{"name":"description","content":"使用海外 VPS 和 x-ui 面板自建 V2Ray/Xray 节点，包含服务器准备、脚本安装、面板安全设置、节点创建和客户端导入流程。"}],["meta",{"name":"keywords","content":"V2Ray,Xray,x-ui,VLESS,VMess,VPS,代理"}]],"layout":"doc"},"headers":[],"relativePath":"vpn/v2ray.md","filePath":"vpn/v2ray.md","lastUpdated":1785199967000}'),h={name:"vpn/v2ray.md"},g=Object.assign(h,{setup(p){return t(),(c,u)=>{const e=i("ImageViewer");return l(),s("div",null,[n,r(e,{src:"https://i-blog.csdnimg.cn/direct/6a0992b03e0242e88018a73bb1cd01c4.png#pic_center"}),d])}}});export{m as __pageData,g as default};
